from datetime import datetime, timedelta
from airflow.sdk import dag, task

@dag(schedule='@daily', start_date=datetime(2026, 1, 1), catchup=False,
     default_args={'retries': 2, 'retry_delay': timedelta(minutes=5)})
def customer_orders():
    @task
    def extract(data_interval_start=None) -> str:
        day = data_interval_start.strftime('%Y-%m-%d')
        return f'landing/orders/dt={day}/orders.parquet'

    @task
    def load(path: str) -> None:
        print(f'overwrite partition from {path}')

    load(extract())

customer_orders()

import dagster as dg
import pandas as pd

@dg.asset
def raw_orders() -> pd.DataFrame:
    return pd.read_parquet('landing/orders.parquet')

@dg.asset
def clean_orders(raw_orders: pd.DataFrame) -> pd.DataFrame:
    return raw_orders.dropna(subset=['order_id']).drop_duplicates('order_id')

defs = dg.Definitions(assets=[raw_orders, clean_orders])
